# Unit test example using pytest
import pytest

def calculate_discount(price, discount_percent):
    if price < 0 or discount_percent < 0:
        raise ValueError("Values cannot be negative")
    return price * (1 - discount_percent / 100)

# Unit Test 1: Valid calculation
def test_calculate_discount_valid():
    assert calculate_discount(200, 10) == 180.0

# Unit Test 2: Exception handling for negative input
def test_calculate_discount_exception():
    with pytest.raises(ValueError):
        calculate_discount(-50, 10)

# Run via terminal: pytest -v

