from unittest.mock import Mock

# External service interface
class PaymentGateway:
    def charge(self, amount):
        pass

# Unit under test
class CheckoutService:
    def __init__(self, gateway):
        self.gateway = gateway

    def checkout(self, amount):
        return self.gateway.charge(amount)

# --- Test using a Mock ---
mock_gateway = Mock()
mock_gateway.charge.return_value = True # Stubbing return value

service = CheckoutService(mock_gateway)
result = service.checkout(100)

# Verifying behavior (Mock aspect)
mock_gateway.charge.assert_called_once_with(100)
print(f"Checkout success: {result}")

